1	// ============================================================================
2	// Aligned Memory Allocator (64-byte Cache-Line Aligned)
3	// FreeLang 구현 - Zero-Copy DB용 메모리 관리자
4	// ============================================================================
5	//
6	// 목표: 모든 메모리 할당을 64바이트 경계에 정렬하여
7	//       CPU 캐시 효율을 극대화하고 SIMD 성능을 최적화
8	//
9	// 원리:
10	//   - CPU L1 캐시라인: 64바이트
11	//   - 정렬 메모리: 캐시라인 경계에서 시작
12	//   - SIMD 연산: 메모리 접근 오버헤드 감소 → 1-2% 추가 성능 향상
13	// ============================================================================
14	
15	module memory {
16	    // ========================================================================
17	    // 상수
18	    // ========================================================================
19	
20	    const CACHE_LINE_SIZE: u32 = 64;          // 캐시라인 크기
21	    const MIN_ALIGNMENT: u32 = 16;            // 최소 정렬 (128비트)
22	    const PAGE_SIZE: u32 = 4096;              // 메모리 페이지 크기
23	    const POOL_INITIAL_SIZE: u32 = 1024;      // 초기 풀 크기
24	
25	    // ========================================================================
26	    // 데이터 구조
27	    // ========================================================================
28	
29	    // MemoryBlock은 할당된 메모리 블록의 메타정보
30	    struct MemoryBlock {
31	        ptr: u64;              // 메모리 포인터
32	        size: u32;             // 할당된 크기
33	        alignment: u32;        // 정렬 바이트
34	        is_aligned: bool;      // 정렬 여부
35	        user_ptr: u64;         // 사용자 포인터 (패딩 이후)
36	    }
37	
38	    // AlignedAllocator는 정렬된 메모리를 관리하는 할당자
39	    struct AlignedAllocator {
40	        alignment: u32;        // 기본 정렬 (64)
41	        blocks: [MemoryBlock]; // 할당된 블록 목록
42	        total_allocated: u64;  // 총 할당 크기
43	        total_wasted: u64;     // 정렬으로 인한 낭비 크기
44	    }
45	
46	    // AlignmentInfo는 정렬 상태 정보
47	    struct AlignmentInfo {
48	        address: u64;
49	        alignment_bytes: u32;
50	        is_aligned: bool;
51	        next_aligned_addr: u64;
52	        padding_needed: u32;
53	    }
54	
55	    // AllocationStats는 할당 통계
56	    struct AllocationStats {
57	        total_blocks: u32;
58	        total_allocated: u64;
59	        total_wasted: u64;
60	        avg_utilization: f32;
61	    }
62	
63	    // ========================================================================
64	    // 정렬 계산 함수
65	    // ========================================================================
66	
67	    // align_up: 주어진 값을 정렬 크기로 올림
68	    // 예: align_up(100, 64) = 128
69	    @inline
70	    func align_up(value: u32, alignment: u32) -> u32 {
71	        if alignment == 0 {
72	            return value;
73	        }
74	        return ((value + alignment - 1) / alignment) * alignment;
75	    }
76	
77	    // align_down: 주어진 값을 정렬 크기로 내림
78	    // 예: align_down(100, 64) = 64
79	    @inline
80	    func align_down(value: u32, alignment: u32) -> u32 {
81	        if alignment == 0 {
82	            return value;
83	        }
84	        return (value / alignment) * alignment;
85	    }
86	
87	    // is_aligned: 값이 정렬되었는지 확인
88	    @inline
89	    func is_aligned(value: u64, alignment: u32) -> bool {
90	        return (value % u64(alignment)) == 0;
91	    }
92	
93	    // calc_padding: 정렬을 위한 패딩 계산
94	    // 반환: (패딩 바이트, 정렬된 주소)
95	    @inline
96	    func calc_padding(ptr: u64, alignment: u32) -> (u32, u64) {
97	        let remainder = u32(ptr % u64(alignment));
98	        if remainder == 0 {
99	            return (0, ptr);
100	        }
101	
102	        let padding = alignment - remainder;
103	        let aligned_addr = ptr + u64(padding);
104	        return (padding, aligned_addr);
105	    }
106	
107	    // ========================================================================
108	    // Branchless 최적화 함수
109	    // ========================================================================
110	
111	    // max_branchless: 분기 없이 최댓값 계산
112	    // if-else를 비트 연산으로 대체하여 파이프라인 중단 방지
113	    @inline
114	    func max_branchless(a: i32, b: i32) -> i32 {
115	        // a >= b 인 경우 a, 아니면 b를 반환
116	        // 분기 대신 비트 마스킹 사용
117	        let diff = a - b;
118	        let sign = (diff >> 31);  // 음수면 -1 (모든 비트 1), 양수면 0
119	        return b + ((a - b) & ~sign);
120	    }
121	
122	    // min_branchless: 분기 없이 최솟값 계산
123	    @inline
124	    func min_branchless(a: i32, b: i32) -> i32 {
125	        let diff = a - b;
126	        let sign = (diff >> 31);
127	        return a - ((a - b) & ~sign);
128	    }
129	
130	    // clamp_branchless: 값을 범위 내로 제한 (분기 없음)
131	    // SIMD 마스킹과 동일한 원리
132	    @inline
133	    func clamp_branchless(value: i32, min: i32, max: i32) -> i32 {
134	        let clamped = max_branchless(min, min_branchless(value, max));
135	        return clamped;
136	    }
137	
138	    // abs_branchless: 절댓값 계산 (분기 없음)
139	    @inline
140	    func abs_branchless(x: i32) -> i32 {
141	        let mask = x >> 31;      // 음수면 -1, 양수면 0
142	        return (x + mask) ^ mask; // XOR로 부호 반전
143	    }
144	
145	    // ========================================================================
146	    // 할당자 생성 및 초기화
147	    // ========================================================================
148	
149	    // new: 새로운 정렬된 할당자 생성
150	    func new() -> AlignedAllocator {
151	        return AlignedAllocator {
152	            alignment: CACHE_LINE_SIZE,
153	            blocks: make([MemoryBlock], 0),
154	            total_allocated: 0,
155	            total_wasted: 0,
156	        };
157	    }
158	
159	    // ========================================================================
160	    // 메모리 할당 함수
161	    // ========================================================================
162	
163	    // allocate: 64바이트 정렬된 메모리 할당
164	    func (a: *AlignedAllocator) allocate(size: u32) -> u64 {
165	        if size == 0 {
166	            panic("Cannot allocate zero bytes");
167	        }
168	
169	        // 할당 크기 = 원본 크기 + 패딩 (최악의 경우 63바이트)
170	        let padded_size = size + (a.alignment - 1);
171	
172	        // 가상 메모리 할당 (실제 구현에서는 malloc 호출)
173	        let ptr = virtual_alloc(padded_size);
174	
175	        // 정렬 계산
176	        let (padding, aligned_ptr) = calc_padding(ptr, a.alignment);
177	
178	        // 블록 정보 기록
179	        let block = MemoryBlock {
180	            ptr: ptr,
181	            size: size,
182	            alignment: a.alignment,
183	            is_aligned: padding == 0,
184	            user_ptr: aligned_ptr,
185	        };
186	
187	        a.blocks.push(block);
188	        a.total_allocated = a.total_allocated + u64(padded_size);
189	        a.total_wasted = a.total_wasted + u64(padding);
190	
191	        return aligned_ptr;
192	    }
193	
194	    // allocate_aligned: 임의의 정렬 값으로 메모리 할당
195	    func (a: *AlignedAllocator) allocate_aligned(size: u32, alignment: u32) -> u64 {
196	        if size == 0 {
197	            panic("Cannot allocate zero bytes");
198	        }
199	
200	        // 정렬 값 검증
201	        let aligned_alignment = max_branchless(i32(alignment), i32(MIN_ALIGNMENT));
202	        let align_u32 = u32(aligned_alignment);
203	
204	        // 할당 크기 조정
205	        let padded_size = size + (align_u32 - 1);
206	
207	        // 메모리 할당
208	        let ptr = virtual_alloc(padded_size);
209	        let (padding, aligned_ptr) = calc_padding(ptr, align_u32);
210	
211	        // 블록 기록
212	        let block = MemoryBlock {
213	            ptr: ptr,
214	            size: size,
215	            alignment: align_u32,
216	            is_aligned: padding == 0,
217	            user_ptr: aligned_ptr,
218	        };
219	
220	        a.blocks.push(block);
221	        a.total_allocated = a.total_allocated + u64(padded_size);
222	        a.total_wasted = a.total_wasted + u64(padding);
223	
224	        return aligned_ptr;
225	    }
226	
227	    // ========================================================================
228	    // 메모리 해제
229	    // ========================================================================
230	
231	    // deallocate: 메모리 해제
232	    func (a: *AlignedAllocator) deallocate(ptr: u64) {
233	        // 블록 찾기
234	        for i = 0; i < len(a.blocks); i = i + 1 {
235	            if a.blocks[i].user_ptr == ptr {
236	                // 메모리 해제
237	                virtual_free(a.blocks[i].ptr, a.blocks[i].size);
238	
239	                // 블록 제거 (간단한 방식)
240	                a.blocks[i] = MemoryBlock {};
241	                break;
242	            }
243	        }
244	    }
245	
246	    // ========================================================================
247	    // 정렬 검증
248	    // ========================================================================
249	
250	    // verify_alignment: 할당된 메모리의 정렬 상태 검증
251	    func (a: *AlignedAllocator) verify_alignment(ptr: u64) -> AlignmentInfo {
252	        let (padding, next_aligned) = calc_padding(ptr, a.alignment);
253	        let aligned = is_aligned(ptr, a.alignment);
254	
255	        return AlignmentInfo {
256	            address: ptr,
257	            alignment_bytes: a.alignment,
258	            is_aligned: aligned,
259	            next_aligned_addr: next_aligned,
260	            padding_needed: padding,
261	        };
262	    }
263	
264	    // check_all_aligned: 모든 할당이 정렬되었는지 확인
265	    func (a: *AlignedAllocator) check_all_aligned() -> bool {
266	        for i = 0; i < len(a.blocks); i = i + 1 {
267	            if !a.blocks[i].is_aligned {
268	                return false;
269	            }
270	        }
271	        return true;
272	    }
273	
274	    // ========================================================================
275	    // 통계
276	    // ========================================================================
277	
278	    // stats: 할당 통계 반환
279	    func (a: *AlignedAllocator) stats() -> AllocationStats {
280	        let total_useful = a.total_allocated - a.total_wasted;
281	        let utilization = f32(total_useful) / f32(a.total_allocated);
282	
283	        return AllocationStats {
284	            total_blocks: u32(len(a.blocks)),
285	            total_allocated: a.total_allocated,
286	            total_wasted: a.total_wasted,
287	            avg_utilization: utilization,
288	        };
289	    }
290	
291	    // print_stats: 통계 출력
292	    func (a: *AlignedAllocator) print_stats() {
293	        let s = a.stats();
294	
295	        print("╔════════════════════════════════════════╗");
296	        print("║ Aligned Allocator Statistics           ║");
297	        print("╠════════════════════════════════════════╣");
298	        print("║ Cache Line Size:     " + CACHE_LINE_SIZE + " bytes");
299	        print("║ Total Blocks:        " + s.total_blocks);
300	        print("║ Total Allocated:     " + s.total_allocated + " bytes");
301	        print("║ Wasted (Padding):    " + s.total_wasted + " bytes");
302	        print("║ Utilization:         " + s.avg_utilization * 100.0 + "%");
303	        print("╚════════════════════════════════════════╝");
304	    }
305	
306	    // ========================================================================
307	    // 가상 메모리 함수 (실제로는 OS 호출)
308	    // ========================================================================
309	
310	    // virtual_alloc: 메모리 할당 (모의)
311	    func virtual_alloc(size: u32) -> u64 {
312	        // 실제 구현에서는:
313	        // - Linux: malloc() 또는 aligned_alloc()
314	        // - Windows: VirtualAlloc()
315	        // - MacOS: malloc_aligned()
316	
317	        // 여기서는 임의의 주소 반환 (테스트용)
318	        return u64(size);
319	    }
320	
321	    // virtual_free: 메모리 해제 (모의)
322	    func virtual_free(ptr: u64, size: u32) {
323	        // 실제 구현에서는 free() 또는 VirtualFree() 호출
324	    }
325	}
326	
327	// ============================================================================
328	// 테스트 코드
329	// ============================================================================
330	
331	func main() {
332	    print("🚀 FreeLang Aligned Allocator 테스트");
333	    print("====================================");
334	    print("");
335	
336	    // 테스트 1: 할당자 생성
337	    print("✅ 테스트 1: 할당자 생성");
338	    let alloc = memory.new();
339	    print("   정렬 크기: " + alloc.alignment + " bytes");
340	    print("");
341	
342	    // 테스트 2: 정렬 계산
343	    print("✅ 테스트 2: 정렬 계산 (align_up)");
344	    let aligned = memory.align_up(100, 64);
345	    print("   align_up(100, 64) = " + aligned);
346	    print("");
347	
348	    // 테스트 3: 패딩 계산
349	    print("✅ 테스트 3: 패딩 계산");
350	    let addr = u64(1000);
351	    let (padding, aligned_addr) = memory.calc_padding(addr, 64);
352	    print("   주소: " + addr);
353	    print("   필요한 패딩: " + padding + " bytes");
354	    print("   정렬된 주소: " + aligned_addr);
355	    print("");
356	
357	    // 테스트 4: Branchless 최댓값
358	    print("✅ 테스트 4: Branchless 연산");
359	    let max_val = memory.max_branchless(10, 20);
360	    print("   max_branchless(10, 20) = " + max_val);
361	    let min_val = memory.min_branchless(10, 20);
362	    print("   min_branchless(10, 20) = " + min_val);
363	    print("");
364	
365	    // 테스트 5: 정렬 검증
366	    print("✅ 테스트 5: 정렬 검증");
367	    let info = alloc.verify_alignment(64);
368	    print("   주소 64는 64바이트 정렬됨: " + info.is_aligned);
369	    let info2 = alloc.verify_alignment(100);
370	    print("   주소 100은 64바이트 정렬됨: " + info2.is_aligned);
371	    print("");
372	
373	    // 테스트 6: 통계
374	    print("✅ 테스트 6: 할당 통계");
375	    alloc.print_stats();
376	    print("");
377	
378	    print("✨ 모든 테스트 완료!");
379	}
