1	// Package parser implements an AST parser for mini FreeLang
2	package parser
3	
4	import (
5		"fmt"
6	
7		"github.com/user/freelang-evolving-compiler/internal/ast"
8		"github.com/user/freelang-evolving-compiler/internal/lexer"
9	)
10	
11	type Parser struct {
12		l         *lexer.Lexer
13		curToken  ast.Token
14		peekToken ast.Token
15	}
16	
17	// New creates a new parser for the input string
18	func New(input string) *Parser {
19		l := lexer.New(input)
20		p := &Parser{l: l}
21		p.nextToken()
22		p.nextToken()
23		return p
24	}
25	
26	func (p *Parser) nextToken() {
27		p.curToken = p.peekToken
28		p.peekToken = p.l.NextToken()
29	}
30	
31	// ParseProgram parses a complete program
32	func (p *Parser) ParseProgram() (*ast.Node, error) {
33		prog := &ast.Node{
34			Kind:     ast.NodeProgram,
35			Children: []*ast.Node{},
36		}
37	
38		for p.curToken.Type != ast.TokenEOF {
39			stmt, err := p.parseStatement()
40			if err != nil {
41				return nil, err
42			}
43			if stmt != nil {
44				prog.Children = append(prog.Children, stmt)
45			}
46			p.skipSemicolons()
47		}
48	
49		return prog, nil
50	}
51	
52	func (p *Parser) parseStatement() (*ast.Node, error) {
53		switch p.curToken.Type {
54		case ast.TokenLet:
55			return p.parseLetDecl()
56		case ast.TokenFn:
57			return p.parseFnDecl()
58		case ast.TokenIf:
59			return p.parseIfStmt()
60		case ast.TokenFor:
61			return p.parseForStmt()
62		case ast.TokenReturn:
63			return p.parseReturnStmt()
64		case ast.TokenLBrace:
65			return p.parseBlockStmt()
66		case ast.TokenSemicolon:
67			p.nextToken()
68			return nil, nil
69		default:
70			// Try to parse as expression statement
71			expr, err := p.parseExpression(0)
72			if err != nil {
73				return nil, err
74			}
75			return expr, nil
76		}
77	}
78	
79	func (p *Parser) parseLetDecl() (*ast.Node, error) {
80		letNode := &ast.Node{
81			Kind: ast.NodeLetDecl,
82			Line: p.curToken.Line,
83			Col:  p.curToken.Col,
84		}
85	
86		p.nextToken() // consume 'let'
87	
88		if p.curToken.Type != ast.TokenIdent {
89			return nil, fmt.Errorf("expected identifier after 'let'")
90		}
91	
92		nameNode := &ast.Node{
93			Kind:  ast.NodeIdent,
94			Value: p.curToken.Value,
95			Line:  p.curToken.Line,
96			Col:   p.curToken.Col,
97		}
98		letNode.Children = append(letNode.Children, nameNode)
99	
100		p.nextToken() // consume identifier
101	
102		if p.curToken.Type != ast.TokenAssign {
103			return nil, fmt.Errorf("expected '=' after identifier")
104		}
105	
106		p.nextToken() // consume '='
107	
108		expr, err := p.parseExpression(0)
109		if err != nil {
110			return nil, err
111		}
112		letNode.Children = append(letNode.Children, expr)
113	
114		return letNode, nil
115	}
116	
117	func (p *Parser) parseFnDecl() (*ast.Node, error) {
118		fnNode := &ast.Node{
119			Kind: ast.NodeFnDecl,
120			Line: p.curToken.Line,
121			Col:  p.curToken.Col,
122		}
123	
124		p.nextToken() // consume 'fn'
125	
126		if p.curToken.Type != ast.TokenIdent {
127			return nil, fmt.Errorf("expected function name")
128		}
129	
130		fnNode.Value = p.curToken.Value
131		p.nextToken()
132	
133		if p.curToken.Type != ast.TokenLParen {
134			return nil, fmt.Errorf("expected '(' after function name")
135		}
136	
137		p.nextToken()
138	
139		// Parse parameters (simplified: just identifiers)
140		for p.curToken.Type != ast.TokenRParen {
141			if p.curToken.Type != ast.TokenIdent {
142				return nil, fmt.Errorf("expected parameter name")
143			}
144			param := &ast.Node{
145				Kind:  ast.NodeIdent,
146				Value: p.curToken.Value,
147			}
148			fnNode.Children = append(fnNode.Children, param)
149			p.nextToken()
150	
151			if p.curToken.Type == ast.TokenColon {
152				p.nextToken()
153				if p.curToken.Type == ast.TokenIdent {
154					p.nextToken() // skip type for now
155				}
156			}
157	
158			if p.curToken.Type == ast.TokenComma {
159				p.nextToken()
160			}
161		}
162	
163		p.nextToken() // consume ')'
164	
165		if p.curToken.Type != ast.TokenLBrace {
166			return nil, fmt.Errorf("expected '{' for function body")
167		}
168	
169		body, err := p.parseBlockStmt()
170		if err != nil {
171			return nil, err
172		}
173		fnNode.Children = append(fnNode.Children, body)
174	
175		return fnNode, nil
176	}
177	
178	func (p *Parser) parseIfStmt() (*ast.Node, error) {
179		ifNode := &ast.Node{
180			Kind: ast.NodeIfStmt,
181			Line: p.curToken.Line,
182			Col:  p.curToken.Col,
183		}
184	
185		p.nextToken() // consume 'if'
186	
187		cond, err := p.parseExpression(0)
188		if err != nil {
189			return nil, err
190		}
191		ifNode.Children = append(ifNode.Children, cond)
192	
193		if p.curToken.Type != ast.TokenLBrace {
194			return nil, fmt.Errorf("expected '{' after if condition")
195		}
196	
197		body, err := p.parseBlockStmt()
198		if err != nil {
199			return nil, err
200		}
201		ifNode.Children = append(ifNode.Children, body)
202	
203		return ifNode, nil
204	}
205	
206	func (p *Parser) parseForStmt() (*ast.Node, error) {
207		forNode := &ast.Node{
208			Kind: ast.NodeForStmt,
209			Line: p.curToken.Line,
210			Col:  p.curToken.Col,
211		}
212	
213		p.nextToken() // consume 'for'
214	
215		if p.curToken.Type != ast.TokenIdent {
216			return nil, fmt.Errorf("expected iterator variable")
217		}
218	
219		iter := &ast.Node{
220			Kind:  ast.NodeIdent,
221			Value: p.curToken.Value,
222		}
223		forNode.Children = append(forNode.Children, iter)
224		p.nextToken()
225	
226		if p.curToken.Type != ast.TokenIn {
227			return nil, fmt.Errorf("expected 'in' after iterator")
228		}
229	
230		p.nextToken()
231	
232		rng, err := p.parseExpression(0)
233		if err != nil {
234			return nil, err
235		}
236		forNode.Children = append(forNode.Children, rng)
237	
238		if p.curToken.Type != ast.TokenLBrace {
239			return nil, fmt.Errorf("expected '{' for loop body")
240		}
241	
242		body, err := p.parseBlockStmt()
243		if err != nil {
244			return nil, err
245		}
246		forNode.Children = append(forNode.Children, body)
247	
248		return forNode, nil
249	}
250	
251	func (p *Parser) parseReturnStmt() (*ast.Node, error) {
252		retNode := &ast.Node{
253			Kind: ast.NodeReturn,
254			Line: p.curToken.Line,
255			Col:  p.curToken.Col,
256		}
257	
258		p.nextToken() // consume 'return'
259	
260		if p.curToken.Type == ast.TokenSemicolon || p.curToken.Type == ast.TokenRBrace {
261			return retNode, nil
262		}
263	
264		expr, err := p.parseExpression(0)
265		if err != nil {
266			return nil, err
267		}
268		retNode.Children = append(retNode.Children, expr)
269	
270		return retNode, nil
271	}
272	
273	func (p *Parser) parseBlockStmt() (*ast.Node, error) {
274		block := &ast.Node{
275			Kind: ast.NodeBlockStmt,
276			Line: p.curToken.Line,
277			Col:  p.curToken.Col,
278		}
279	
280		p.nextToken() // consume '{'
281	
282		for p.curToken.Type != ast.TokenRBrace && p.curToken.Type != ast.TokenEOF {
283			stmt, err := p.parseStatement()
284			if err != nil {
285				return nil, err
286			}
287			if stmt != nil {
288				block.Children = append(block.Children, stmt)
289			}
290			p.skipSemicolons()
291		}
292	
293		if p.curToken.Type != ast.TokenRBrace {
294			return nil, fmt.Errorf("expected '}'")
295		}
296	
297		p.nextToken() // consume '}'
298	
299		return block, nil
300	}
301	
302	func (p *Parser) parseExpression(prec int) (*ast.Node, error) {
303		left, err := p.parsePrimary()
304		if err != nil {
305			return nil, err
306		}
307	
308		for prec < p.peekPrecedence() {
309			p.nextToken()
310			left, err = p.parseInfix(left)
311			if err != nil {
312				return nil, err
313			}
314		}
315	
316		return left, nil
317	}
318	
319	func (p *Parser) parsePrimary() (*ast.Node, error) {
320		switch p.curToken.Type {
321		case ast.TokenInt:
322			node := &ast.Node{
323				Kind:  ast.NodeIntLit,
324				Value: p.curToken.Value,
325				Line:  p.curToken.Line,
326				Col:   p.curToken.Col,
327			}
328			return node, nil
329	
330		case ast.TokenIdent:
331			node := &ast.Node{
332				Kind:  ast.NodeIdent,
333				Value: p.curToken.Value,
334				Line:  p.curToken.Line,
335				Col:   p.curToken.Col,
336			}
337			return node, nil
338	
339		case ast.TokenLParen:
340			p.nextToken()
341			expr, err := p.parseExpression(0)
342			if err != nil {
343				return nil, err
344			}
345			if p.curToken.Type != ast.TokenRParen {
346				return nil, fmt.Errorf("expected ')'")
347			}
348			return expr, nil
349	
350		default:
351			return nil, fmt.Errorf("unexpected token: %v", p.curToken.Type)
352		}
353	}
354	
355	func (p *Parser) parseInfix(left *ast.Node) (*ast.Node, error) {
356		node := &ast.Node{
357			Kind: ast.NodeBinaryExpr,
358			Line: p.curToken.Line,
359			Col:  p.curToken.Col,
360			Value: p.curToken.Value,
361			Children: []*ast.Node{left},
362		}
363	
364		prec := p.curPrecedence()
365		p.nextToken()
366	
367		right, err := p.parseExpression(prec)
368		if err != nil {
369			return nil, err
370		}
371		node.Children = append(node.Children, right)
372	
373		// Handle function calls
374		if left.Kind == ast.NodeIdent && p.curToken.Type == ast.TokenLParen {
375			call := &ast.Node{
376				Kind:  ast.NodeCallExpr,
377				Value: left.Value,
378			}
379			p.nextToken() // consume '('
380			for p.curToken.Type != ast.TokenRParen {
381				arg, err := p.parseExpression(0)
382				if err != nil {
383					return nil, err
384				}
385				call.Children = append(call.Children, arg)
386				if p.curToken.Type == ast.TokenComma {
387					p.nextToken()
388				}
389			}
390			p.nextToken() // consume ')'
391			return call, nil
392		}
393	
394		return node, nil
395	}
396	
397	func (p *Parser) peekPrecedence() int {
398		return precedence(p.peekToken.Type)
399	}
400	
401	func (p *Parser) curPrecedence() int {
402		return precedence(p.curToken.Type)
403	}
404	
405	func precedence(tok ast.TokenType) int {
406		switch tok {
407		case ast.TokenEq, ast.TokenNe, ast.TokenLt, ast.TokenGt, ast.TokenLe, ast.TokenGe:
408			return 1
409		case ast.TokenPlus, ast.TokenMinus:
410			return 2
411		case ast.TokenStar, ast.TokenSlash:
412			return 3
413		case ast.TokenDotDot:
414			return 4
415		default:
416			return 0
417		}
418	}
419	
420	func (p *Parser) skipSemicolons() {
421		for p.curToken.Type == ast.TokenSemicolon {
422			p.nextToken()
423		}
424	}
